     start = start || 0;
     var n = Buffer.isBuffer(needle) ? needle : Buffer.from(String(needle));
     outer: for (var i = start; i + n.length <= this.length; i++) {
       for (var j = 0; j < n.length; j++) { if (this[i + j] !== n[j]) { continue outer; } }
       return i;
     }
     return -1;
   };
