                     val name = entry.name
                     val wanted = name.startsWith("include/node/") ||
                         nodeMobileAbis.any { name == "bin/$it/libnode.so" }
                     if (wanted && !entry.isDirectory) {
                         val target = File(nodeMobileDir, name)
                         target.parentFile?.mkdirs()
